WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.ViewCount, p.AnswerCount, p.CommentCount, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS PostRank FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), UserStats AS (SELECT u.Id AS UserId, u.DisplayName, u.Reputation, COALESCE(SUM(CASE WHEN v.VoteTypeId = 2 THEN 1 ELSE 0 END), 0) AS TotalUpvotes, COALESCE(SUM(CASE WHEN v.VoteTypeId = 3 THEN 1 ELSE 0 END), 0) AS TotalDownvotes, COALESCE(SUM(CASE WHEN b.Class = 1 THEN 1 ELSE 0 END), 0) AS GoldBadges, COALESCE(SUM(b.Class) FILTER(WHERE NOT (b.Class IS NULL)), 0) AS TotalBadges FROM Users AS u LEFT JOIN Votes AS v ON u.Id = v.UserId LEFT JOIN Badges AS b ON u.Id = b.UserId GROUP BY u.Id, u.DisplayName, u.Reputation), PostHistoryWithCloseReasons AS (SELECT ph.PostId, ph.CreationDate, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph LEFT JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.PostId, ph.CreationDate) SELECT us.DisplayName, us.Reputation, us.TotalUpvotes, us.TotalDownvotes, us.GoldBadges, us.TotalBadges, rp.Title, rp.CreationDate AS PostCreationDate, rp.Score, rp.ViewCount, rp.AnswerCount, rp.CommentCount, ph.CloseReasons FROM UserStats AS us JOIN RankedPosts AS rp ON us.UserId = rp.PostId LEFT JOIN PostHistoryWithCloseReasons AS ph ON rp.PostId = ph.PostId WHERE rp.PostRank <= 3 ORDER BY us.Reputation DESC NULLS FIRST, rp.ViewCount DESC NULLS FIRST LIMIT 100